import { Accessor, createEffect, createMemo, createSignal, ParentComponent, Setter, useContext } from "solid-js";

import { FxsTextboxValidateVirtualKeyboard, TextBoxTextEditStopEvent } from "#core/ui/components/fxs-textbox.js";
import { InputEngineEvent } from "#core/ui/input/input-support.js";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { AudioGroupContext } from "#core/ui-next/services/audio.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";
import { isFocusable } from "#core/ui-next/services/focus.js";
import { registerHotkey } from "#core/ui-next/services/hotkey.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { createPropsRefSignal, PropsRef } from "#core/ui-next/utilities/solid-utilities.js";

export interface TextInputProps {
	value: Accessor<string>;
	setValue: Setter<string>;
	placeholder?: string;
	enableVirtualKeyboard?: boolean;
	ref?: PropsRef<HTMLInputElement>;
	class?: string;
	disabled?: boolean;
	disableFocus?: boolean;
	autoFocus?: boolean;
	setIsEditing?: Setter<boolean>;
	hotkeyAction?: string;
	tabIndex?: number;
}

const TextInputComponent: ParentComponent<TextInputProps> = (props) => {
	// Note that the audio context is an accessor, and must be called before using
	const audioContext = useContext(AudioGroupContext);
	const [root, setRoot] = createPropsRefSignal<HTMLInputElement>(() => props.ref);
	const [isFocused, setIsFocused] = createSignal(false);

	// We need to force updates when validation fails which will set the string to what it was previously
	// This means we need to turn off equality detection
	const [validatedValue, setValidatedValue] = createSignal("", { equals: () => false });

	const audioTrigger = useAudio();

	const enabled = createMemo(() => !(props.disabled ?? false));

	// Trigger audio from context, this is to prevent duplicate audio from playing.
	function triggerUiSFX(eventName: string, attributeName: string) {
		if (!root()?.hasAttribute(attributeName)) {
			audioTrigger("TextInput", eventName);
		} else {
			audioContext().playSound(attributeName, root());
		}
	}

	createEffect(() => {
		setValidatedValue(props.value?.());
	});

	createEffect(() => {
		props.setIsEditing?.(isFocused);
	});

	function onVirtualKeyboardTextEntered(text: GenericDataString) {
		const input = root();

		if (!input) {
			return;
		}

		// for now text is GenericData<std::string>
		let value =
			UI.getIMEConfirmationValueLocation() == IMEConfirmationValueLocation.Element ? input.value : text.data;

		if (input.hasAttribute("max-length")) {
			const maxLength: number = Number.parseInt(input.getAttribute("max-length") ?? "-1");

			if (maxLength > 0 && value.length > maxLength) {
				value = value.substring(0, maxLength);
			}
		}

		updateValue(value);
		input.dispatchEvent(new FxsTextboxValidateVirtualKeyboard({ value }));

		// we the text and IME will close, clear callbacks now
		clearVirtualKeyboardCallbacks();
		input.dispatchEvent(new TextBoxTextEditStopEvent(true));
	}

	//function triggered when canceling text entry on a virtual keyboard (applicable to consoles)
	function onVirtualKeyboardTextCanceled() {
		clearVirtualKeyboardCallbacks();
		root()?.dispatchEvent(new TextBoxTextEditStopEvent(false));
	}

	//clear listeners for virtual keyboard text entry
	function clearVirtualKeyboardCallbacks() {
		engine.off("IMEValidated", onVirtualKeyboardTextEntered);
		engine.off("IMECanceled", onVirtualKeyboardTextCanceled);
	}

	function onActivate() {
		triggerUiSFX("activate", "data-audio-activate");

		// Register Virtual Keyboard callbacks
		if (UI.canDisplayKeyboard() && props.enableVirtualKeyboard) {
			engine.on("IMEValidated", onVirtualKeyboardTextEntered);
			engine.on("IMECanceled", onVirtualKeyboardTextCanceled);

			UI.displayKeyboard(root()?.value ?? "", root()?.type == "password", root()?.maxLength ?? -1);
		}

		if (IsControllerActive()) {
			switch (UI.getVirtualKeyboardType()) {
				case UIVirtualKeyboardType.None:
				case UIVirtualKeyboardType.Inline:
					//Do the focus stuff that inherently happens via click
					if (root() !== undefined) {
						FocusManager.get().setFocus(root()!);
					}
					break;

				default:
					break;
			}
		}
	}

	function updateValue(value: string) {
		// Check if the setter modified the value, if so we need to update the validated value
		const newValue = props.setValue(value);
		if (newValue !== undefined && value != newValue) {
			setValidatedValue(newValue);
		}
	}

	function onDoubleClick() {
		root()?.setSelectionRange(0, -1);
	}

	function onMouseEnter() {
		triggerUiSFX("focus", "data-audio-focus");
	}

	function onEngineInput(inputEvent: InputEngineEvent) {
		if (inputEvent.detail.status != InputActionStatuses.FINISH) {
			return;
		}

		const input = root();
		if (!input) {
			return;
		}

		if (inputEvent.detail.name == "accept" && enabled()) {
			onActivate();
			inputEvent.stopPropagation();
			inputEvent.preventDefault();
		} else if (inputEvent.isCancelInput() && enabled()) {
			input.dispatchEvent(new TextBoxTextEditStopEvent(false, inputEvent.detail.name));
			inputEvent.stopPropagation();
			inputEvent.preventDefault();
		} else if (inputEvent.detail.name == "touch-tap" && enabled()) {
			onActivate();
			inputEvent.stopPropagation();
			inputEvent.preventDefault();
		}
	}

	return (
		<div
			class={`relative flex flex-row ${props.class ?? ""}`}
			use:registerHotkey={[props.hotkeyAction, () => enabled(), onActivate]}
		>
			<input
				ref={setRoot}
				type={"text"}
				class={`fxs-textbox py-1 px-1\\.5 flex-auto border-1 border-primary-1 hover\\:border-secondary focus\\:border-secondary transition-border-color bg-accent-6`}
				classList={{ "border-secondary": isFocused() }}
				data-name="text-input"
				data-isInput="true"
				onDblClick={onDoubleClick}
				onClick={onActivate}
				on:engine-input={onEngineInput}
				onMouseEnter={onMouseEnter}
				onFocus={() => setIsFocused(true)}
				onFocusOut={() => setIsFocused(false)}
				value={validatedValue()}
				onInput={(e) => updateValue(e.currentTarget.value)}
				attr:consume-keyboard-input={true}
				tabIndex={props.tabIndex}
				use:isFocusable={[!props.disabled && !props.disableFocus, props.autoFocus]}
			/>
			{props.children}
		</div>
	);
};

export const TextInput = ComponentRegistry.register({
	name: "TextInput",
	createInstance: TextInputComponent,
});
